const NAVY = '#183466';
const BADGE = { cx: 280.5, cy: 440.5, r: 59.5 };

// Fruit pieces, three tones each.
const CHERRY = [[0, -.78], [.25, -1.02, .98, -.95, 1, -.15], [1.02, .6, .5, 1, 0, 1], [-.5, 1, -1.02, .6, -1, -.15], [-.98, -.95, -.25, -1.02, 0, -.78]];
const shapeAt = (pts, cx, cy, r) => pts.map((q, i) => (i ? 'C' : 'M') + q.reduce((a, v, k) => a.concat(k % 2 ? [] : [`${X(cx + v * r)} ${Y(cy + q[k + 1] * r)}`]), []).join(' ')).join('') + 'Z';
function cherry([cx, cy, r]) {
  return `<path d="${shapeAt(CHERRY, cx, cy, r)}" fill="${ref('cherry')}"/>`
    + `<path d="M${pt(cx, cy, r * .74, 160)}A${r2(r * .74 * .302)} ${r2(r * .74 * .335)} 0 0 1 ${pt(cx, cy, r * .74, 235)}" fill="none" stroke="#eba2cf" stroke-width="${r2(r * .07)}" stroke-linecap="round" opacity=".9"/>`
    + ell(cx - r * .3, cy - r * .55, r * .11, 'fill="#f6c6e2" opacity=".8"')
    + ell(cx, cy - r * .78, r * .12, 'fill="#3f0a27" opacity=".6"');
}
function leaf(cx, cy, len, w, ang) {
  const a = len * .302 / 2, b = w * .335 / 2;
  return `<g transform="translate(${X(cx)} ${Y(cy)}) rotate(${ang})"><path d="M${r2(-a)} 0Q0 ${r2(-b * 2)} ${r2(a)} 0Q0 ${r2(b * 2)} ${r2(-a)} 0Z" fill="#4c9c3d"/><path d="M${r2(-a)} 0Q0 ${r2(b * 2)} ${r2(a)} 0Z" fill="#2f7630"/><path d="M${r2(-a * .9)} 0Q0 ${r2(-b * .3)} ${r2(a * .9)} 0" fill="none" stroke="#9fd27a" stroke-width=".45"/></g>`;
}
const stem = d => `<path d="${d}" fill="none" stroke="#3c8a37" stroke-width="1.1" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#86c460" stroke-width=".35" stroke-linecap="round" transform="translate(-.25 0)"/>`;
// path in packshot pixels -> units
const P = s => s.replace(/(-?\d+(?:\.\d+)?) (-?\d+(?:\.\d+)?)/g, (_, x, y) => `${X(+x)} ${Y(+y)}`);
const dotPath = (list, k, dx, dy) => list.map(([x, y, rr]) => { const rx = r2(rr * k * .302), ry = r2(rr * k * .335); return `M${r2(X(x + dx * rr) - rx)} ${Y(y + dy * rr)}a${rx} ${ry} 0 1 0 ${r2(2 * rx)} 0a${rx} ${ry} 0 1 0 ${r2(-2 * rx)} 0`; }).join('');
// Painted berry: dark base, uneven mid-tone drupelets (darker to the lower right), highlights upper left.
const jit = (i, k) => r2(((i * 37 + k * 11) % 17) / 17 - .5);
function raspberry([cx, cy, r], n) {
  const base = [[0, -1], [.62, -.95, .95, -.45, .9, .1], [.85, .7, .4, 1.08, 0, 1.08], [-.4, 1.08, -.85, .7, -.9, .1], [-.95, -.45, -.62, -.95, 0, -1]];
  const tones = [[], [], []], hi = [];
  const rows = [[-.62, [-.22, .22]], [-.25, [-.5, 0, .5]], [.15, [-.55, -.05, .45]], [.52, [-.38, .14]], [.82, [-.08]]];
  let i = n * 7;
  for (const [v, us] of rows) for (const u of us) {
    i++;
    const x = cx + (u + jit(i, 1) * .14) * r, y = cy + (v + jit(i, 2) * .12) * r * 1.05, d = r * (.27 + jit(i, 3) * .08);
    const t = u + v; tones[t < -.45 ? 0 : t > .35 ? 2 : 1].push([x, y, d]);
    if (t < -.2) hi.push([x - d * .35, y - d * .4, d * .3]);
  }
  return `<path d="${shapeAt(base, cx, cy, r)}" fill="#7a0b3a"/>`
    + ['#d23676', '#bf1c63', '#9a1150'].map((c, k) => tones[k].length ? `<path d="${dotPath(tones[k], 1, 0, 0)}" fill="${c}"/>` : '').join('')
    + `<path d="${dotPath(hi, 1, 0, 0)}" fill="#f6a3cb"/>`
    + [-35, 35].map(a => leaf(cx + Math.sin(a * Math.PI / 180) * r * .42, cy - r * 1.02, r * .8, r * .32, a)).join('');
}
function lime([cx, cy, r, a0]) {
  const a1 = a0 + 180, lines = [];
  for (let a = a0 + 22; a < a1 - 8; a += 34) lines.push(`M${pt(cx, cy, r * .13, a)}L${pt(cx, cy, r * .82, a)}`);
  return sector(cx, cy, r, a0, a1, '#2e8a2b') + sector(cx, cy, r * .93, a0, a1, '#e6f6c4')
    + sector(cx, cy, r * .86, a0, a1, ref('flesh'))
    + `<path d="${lines.join('')}" fill="none" stroke="#e9f9cf" stroke-width=".7"/>`
;
}

const DEFS = {
  cherry: `<radialGradient id="__ID__cherry" cx=".36" cy=".34" r=".72"><stop offset="0" stop-color="#a23a7e"/><stop offset=".55" stop-color="#7d2059"/><stop offset="1" stop-color="#4a0b2e"/></radialGradient>`,
    flesh: `<radialGradient id="__ID__flesh" cx=".5" cy=".5" r=".6"><stop offset="0" stop-color="#d4f39c"/><stop offset=".6" stop-color="#9fd75a"/><stop offset="1" stop-color="#5fb52f"/></radialGradient>`,
};
const baseDefs = `<clipPath id="__ID__badgeclip">${ell(BADGE.cx, BADGE.cy, BADGE.r - 4, '')}</clipPath>`
  + `<linearGradient id="__ID__topshade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6e6e72" stop-opacity=".75"/><stop offset="1" stop-color="#6e6e72" stop-opacity="0"/></linearGradient>`;

function bubbles() {
  const spots = [[40, 40, 7], [70, 30, 5], [118, 38, 6], [176, 33, 8], [220, 42, 6], [262, 36, 7], [94, 84, 5], [200, 86, 6], [250, 80, 5], [32, 78, 5],
    [60, 545, 6], [210, 545, 7], [250, 528, 5], [110, 395, 5], [240, 560, 5], [280, 545, 6]];
  return `<g fill="none" stroke="#fff" stroke-width=".55" opacity=".55">${spots.map(([x, y, r]) => ell(x, y, r, '')).join('')}</g>`;
}

function polar(slug, title, { block, name, art, defs }) {
  const label = `<path d="M40 41H160V${Y(92)}H40Z" fill="${ref('topshade')}"/>
${bubbles()}
<path d="M40 ${Y(93)}H160V${Y(338)}H40Z" fill="${block}"/>
<path d="M40 ${Y(338)}H160V${Y(390)}H40Z" fill="#f5f5f6"/>
<path d="${REFRESHINGLY}" fill="${NAVY}" fill-rule="evenodd"/>
${art}
<path d="${POLAR_MARK}" fill="#fff" fill-rule="evenodd" stroke="#1c2452" stroke-width=".4" stroke-opacity=".8"/>
<path d="${name}" fill="${NAVY}" fill-rule="evenodd"/>
${ell(BADGE.cx, BADGE.cy, BADGE.r, 'fill="#fbfbfc"')}
<g clip-path="${ref('badgeclip')}"><path d="${BADGE_NAVY}" fill="${NAVY}" fill-rule="evenodd"/></g>
${ell(BADGE.cx, BADGE.cy, BADGE.r - 2.2, `fill="none" stroke="${NAVY}" stroke-width="1.6"`)}`;
  return can(slug, title, label, '#d3d3d5', baseDefs + defs.map(k => DEFS[k]).join(''));
}

