const bublyCan=(slug,title,label,{t=41,l=55,color='#f4f2e9',gold=false}={})=>{
 const r=200-l,rx=100-l-6,shape=`M${l+6} ${t}Q100 ${t-9} ${r-6} ${t}L${r} ${t+17}V220Q${r} 233 100 233T${l} 220V${t+17}Z`;
 return wrap(slug,title,`${shadow(55)}<path d="${shape}" fill="${color}"/><g clip-path="${ref('canclip')}">${label}<path d="${shape}" fill="${ref('shade')}"/><path d="M${l+9} ${t+21}V214" stroke="#fff" stroke-opacity=".20" stroke-width="2.8"/></g><ellipse cx="100" cy="${t}" rx="${rx}" ry="8" fill="${ref('metal')}" stroke="${gold?'#ba9342':'#9ca7a4'}" stroke-width="1.2"/><ellipse cx="100" cy="${t}" rx="${rx-5}" ry="5.4" fill="none" stroke="${gold?'#c2a04e':'#8d9892'}" stroke-width=".8"/><ellipse cx="104" cy="${t+1}" rx="8" ry="3.5" fill="#657169"/><path d="M93 ${t-2}h10q6 0 5 4t-8 3h-6q-6-1-1-7" fill="none" stroke="${gold?'#ead590':'#e6e8de'}" stroke-width="2.4"/><path d="M${l+3} 226q${r-l-6>>1} 12 ${r-l-6} 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/><path d="M${l+6} 230q${r-l-12>>1} 7 ${r-l-12} 0" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1"/>`,`<clipPath id="__ID__canclip"><path d="${shape}"/></clipPath>`);
};
const bublyLogo=`<g stroke="#fffdf5" stroke-width="3.2" fill="none" stroke-linecap="round"><path d="M66 109v26m0-8c0-12 16-12 16 0s-16 12-16 0M88 126c0 12 14 12 14 0M108 109v26m0-8c0-12 16-12 16 0s-16 12-16 0M130 109v22q0 4 3 4m3-14 6 13m6-13-10 25"/></g>`;
const dots=c=>Array.from({length:25},(_,i)=>{const x=53+(i*31)%96,y=47+(i*17)%39,r=1.3+(i*7)%5;return `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/><circle cx="${200-x}" cy="${226-(y-47)*.75}" r="${Math.round(r*80)/100}" fill="${c}"/>`}).join('');
// Mango with the siblings' layout (wordmark, "sparkling water", flavor name, flavor line). What the
// real mango can differs in: a golden-yellow body, red-orange dots, the flavor name in red.
function bublyMango({ body, dot, name }) {
  return bublyCan('bubly-mango', 'bubly mango', `${dots(dot)}<g transform="translate(-5 0)">${bublyLogo}</g>${text(100, 148, 'sparkling water', 7.3, '#fff9e9', 'letter-spacing=".3"')}${text(100, 189, 'mango', 12, name, 'font-weight="bold"')}${text(100, 199, 'flavor with other natural flavors', 4.5, '#f9f1d8')}`, { color: body });
}

